-- Revision-two layout records are separate from the revision-one archive, so old builds
-- can retain newer records without trying to project them into their narrower schema.
CREATE TABLE IF NOT EXISTS _news_dav_layout_values(kind TEXT NOT NULL,feed TEXT NOT NULL,value INTEGER NOT NULL CHECK(value IN (0,1)),label TEXT NOT NULL,PRIMARY KEY(kind,feed));
CREATE TABLE IF NOT EXISTS _news_dav_layout_pending(kind TEXT NOT NULL,feed TEXT NOT NULL,value INTEGER NOT NULL CHECK(value IN (0,1)),label TEXT NOT NULL,PRIMARY KEY(kind,feed));
CREATE TABLE IF NOT EXISTS _news_dav_layout_seeded(id INTEGER PRIMARY KEY CHECK(id=1));
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_folder_add AFTER INSERT ON folders WHEN (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('collection',CAST(NEW.id AS TEXT),1,NEW.name) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label;
INSERT INTO _news_dav_layout_pending VALUES('collection_order',CAST(NEW.id AS TEXT),0,CAST(NEW.position AS TEXT)) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label;
INSERT INTO _news_dav_layout_pending VALUES('collection_sort',CAST(NEW.id AS TEXT),0,NEW.sort) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_collection AFTER UPDATE OF name ON folders WHEN NEW.name IS NOT OLD.name AND (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('collection',CAST(NEW.id AS TEXT),1,NEW.name) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_collection_order AFTER UPDATE OF position ON folders WHEN NEW.position IS NOT OLD.position AND (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('collection_order',CAST(NEW.id AS TEXT),0,CAST(NEW.position AS TEXT)) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_collection_sort AFTER UPDATE OF sort ON folders WHEN NEW.sort IS NOT OLD.sort AND (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('collection_sort',CAST(NEW.id AS TEXT),0,NEW.sort) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_folder_delete BEFORE DELETE ON folders WHEN (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('collection',CAST(OLD.id AS TEXT),0,COALESCE((SELECT label FROM _news_dav_layout_values WHERE kind='collection' AND feed=CAST(OLD.id AS TEXT)),OLD.name)) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_feed_add AFTER INSERT ON feeds WHEN NEW.sync_account IS NULL AND (NEW.feed_url LIKE 'https://%' OR NEW.feed_url LIKE 'http://%') AND (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('membership',NEW.feed_url,0,COALESCE(CAST(NEW.folder AS TEXT),'')) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; INSERT INTO _news_dav_layout_pending VALUES('feed_order',NEW.feed_url,0,CAST(NEW.collection_position AS TEXT)) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; INSERT INTO _news_dav_layout_pending VALUES('priority',NEW.feed_url,0,CAST(NEW.position AS TEXT)) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_membership AFTER UPDATE OF folder ON feeds WHEN NEW.folder IS NOT OLD.folder AND NEW.sync_account IS NULL AND (NEW.feed_url LIKE 'https://%' OR NEW.feed_url LIKE 'http://%') AND (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('membership',NEW.feed_url,0,COALESCE(CAST(NEW.folder AS TEXT),'')) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_feed_order AFTER UPDATE OF collection_position ON feeds WHEN NEW.collection_position IS NOT OLD.collection_position AND NEW.sync_account IS NULL AND (NEW.feed_url LIKE 'https://%' OR NEW.feed_url LIKE 'http://%') AND (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('feed_order',NEW.feed_url,0,CAST(NEW.collection_position AS TEXT)) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
CREATE TRIGGER IF NOT EXISTS _news_dav_layout_priority AFTER UPDATE OF position ON feeds WHEN NEW.position IS NOT OLD.position AND NEW.sync_account IS NULL AND (NEW.feed_url LIKE 'https://%' OR NEW.feed_url LIKE 'http://%') AND (SELECT projecting FROM _news_dav_guard)=0 BEGIN INSERT INTO _news_dav_layout_pending VALUES('priority',NEW.feed_url,0,CAST(NEW.position AS TEXT)) ON CONFLICT(kind,feed) DO UPDATE SET value=excluded.value,label=excluded.label; END;
